<?php
if(!defined('ABSPATH'))exit;
function legacyx_staff_command_menu(){add_menu_page('Legacy X Firm OS','Firm OS','manage_options','legacyx-firm-os','legacyx_render_staff_command','dashicons-chart-area',2);}add_action('admin_menu','legacyx_staff_command_menu');
function legacyx_staff_count($type,$statuses=array('publish','private','draft','pending')){$c=0;foreach((array)$statuses as $s){$q=wp_count_posts($type);if($q&&isset($q->$s))$c+=(int)$q->$s;}return $c;}
function legacyx_staff_meta_count($type,$key,$values){$q=new WP_Query(array('post_type'=>$type,'post_status'=>'any','posts_per_page'=>1,'fields'=>'ids','meta_query'=>array(array('key'=>$key,'value'=>(array)$values,'compare'=>'IN'))));return (int)$q->found_posts;}
function legacyx_render_staff_command(){if(!current_user_can('manage_options'))return;$clients=legacyx_staff_count('legacyx_client');$assessments=legacyx_staff_count('legacyx_assessment');$apps=legacyx_staff_count('legacyx_application');$active_apps=legacyx_staff_meta_count('legacyx_application','_legacyx_status',array('Draft','Preparing','Ready','Submitted','Under Review','Additional Information Requested'));$work=legacyx_staff_count('legacyx_work_item');$open_work=legacyx_staff_meta_count('legacyx_work_item','_legacyx_work_status',array('Open','In Progress','Waiting on Client','Submitted','Under Review'));$invoices=legacyx_staff_count('legacyx_invoice');$open_invoices=legacyx_staff_meta_count('legacyx_invoice','_legacyx_status',array('Open','Partially Paid','Past Due'));$all_clients=get_posts(array('post_type'=>'legacyx_client','post_status'=>'any','numberposts'=>-1));$balance=0;foreach($all_clients as $c){$b=legacyx_billing_counts($c->ID);$balance+=(float)$b['balance'];}$recent=get_posts(array('post_type'=>array('legacyx_client','legacyx_application','legacyx_work_item','legacyx_invoice','legacyx_assessment'),'post_status'=>'any','numberposts'=>8,'orderby'=>'modified','order'=>'DESC'));?>
<div class="wrap legacyx-staff-os"><div class="legacyx-staff-hero"><div><span>LEGACY X FIRM OS · STAFF</span><h1>Executive Command Center</h1><p>One operational view across client relationships, assessments, applications, workflow, credit, business readiness and billing.</p></div><a href="<?php echo esc_url(home_url('/client-portal/'));?>" target="_blank" rel="noopener">Open Client Portal ↗</a></div>
<div class="legacyx-staff-metrics"><div><span>Clients</span><strong><?php echo esc_html($clients);?></strong><small>Universal profiles</small></div><div><span>Assessments</span><strong><?php echo esc_html($assessments);?></strong><small>Executive intake</small></div><div><span>Active Applications</span><strong><?php echo esc_html($active_apps);?></strong><small><?php echo esc_html($apps);?> total</small></div><div><span>Open Workflow</span><strong><?php echo esc_html($open_work);?></strong><small><?php echo esc_html($work);?> total items</small></div><div><span>Open Billing</span><strong><?php echo esc_html($open_invoices);?></strong><small><?php echo esc_html($invoices);?> billing records</small></div><div><span>Outstanding</span><strong><?php echo esc_html(legacyx_money($balance));?></strong><small>Across client profiles</small></div></div>
<div class="legacyx-staff-grid"><section><div class="legacyx-staff-section-head"><span>OPERATIONS</span><h2>Firm Modules</h2></div><div class="legacyx-staff-modules"><?php $mods=array(array('Clients','Universal client profiles','edit.php?post_type=legacyx_client','Manage Clients'),array('Assessments','Executive intake pipeline','edit.php?post_type=legacyx_assessment','Review Assessments'),array('Applications','Funding, grants and service applications','edit.php?post_type=legacyx_application','Manage Applications'),array('Documents & Tasks','Client workflow and document requests','edit.php?post_type=legacyx_work_item','Manage Workflow'),array('Billing & Payments','Invoices, retainers and payment records','edit.php?post_type=legacyx_invoice','Manage Billing'));foreach($mods as $m):?><article><span><?php echo esc_html($m[0]);?></span><h3><?php echo esc_html($m[1]);?></h3><a href="<?php echo esc_url(admin_url($m[2]));?>"><?php echo esc_html($m[3]);?> →</a></article><?php endforeach;?></div></section><aside><div class="legacyx-staff-section-head"><span>QUICK ACTIONS</span><h2>Create</h2></div><a class="legacyx-staff-action" href="<?php echo esc_url(admin_url('post-new.php?post_type=legacyx_client'));?>">+ New Client</a><a class="legacyx-staff-action" href="<?php echo esc_url(admin_url('post-new.php?post_type=legacyx_application'));?>">+ New Application</a><a class="legacyx-staff-action" href="<?php echo esc_url(admin_url('post-new.php?post_type=legacyx_work_item'));?>">+ New Task / Document</a><a class="legacyx-staff-action" href="<?php echo esc_url(admin_url('post-new.php?post_type=legacyx_invoice'));?>">+ New Invoice</a></aside></div>
<section class="legacyx-staff-recent"><div class="legacyx-staff-section-head"><span>RECENT ACTIVITY</span><h2>Latest Records</h2></div><table><thead><tr><th>Record</th><th>Module</th><th>Updated</th><th></th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="4">No records yet.</td></tr><?php else:foreach($recent as $r):$obj=get_post_type_object($r->post_type);?><tr><td><strong><?php echo esc_html(get_the_title($r)?:'(Untitled)');?></strong></td><td><?php echo esc_html($obj?$obj->labels->singular_name:$r->post_type);?></td><td><?php echo esc_html(get_the_modified_date('M j, Y g:i a',$r));?></td><td><a href="<?php echo esc_url(get_edit_post_link($r->ID));?>">Open →</a></td></tr><?php endforeach;endif;?></tbody></table></section></div><?php }
function legacyx_staff_command_styles($hook){if($hook!=='toplevel_page_legacyx-firm-os')return;wp_register_style('legacyx-staff-os',false);wp_enqueue_style('legacyx-staff-os');$css='.legacyx-staff-os{max-width:1440px;margin:24px 24px 60px 4px;color:#171512}.legacyx-staff-hero{background:#171512;color:#fff;padding:34px 38px;display:flex;justify-content:space-between;align-items:flex-end;border-radius:4px}.legacyx-staff-hero span,.legacyx-staff-section-head span{font-size:11px;font-weight:800;letter-spacing:.16em;color:#f05a16}.legacyx-staff-hero h1{font-family:Georgia,serif;font-size:38px;margin:8px 0}.legacyx-staff-hero p{max-width:760px;color:#c9c3ba;font-size:15px}.legacyx-staff-hero>a{background:#f05a16;color:#fff;text-decoration:none;padding:13px 18px;font-weight:700}.legacyx-staff-metrics{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid #ded8ce;background:#fff;margin-top:18px}.legacyx-staff-metrics>div{padding:22px;border-right:1px solid #ded8ce}.legacyx-staff-metrics>div:last-child{border:0}.legacyx-staff-metrics span,.legacyx-staff-metrics small{display:block;color:#746e65}.legacyx-staff-metrics strong{display:block;font-family:Georgia,serif;font-size:28px;margin:7px 0}.legacyx-staff-grid{display:grid;grid-template-columns:3fr 1fr;gap:18px;margin-top:18px}.legacyx-staff-grid>section,.legacyx-staff-grid>aside,.legacyx-staff-recent{background:#fff;border:1px solid #ded8ce;padding:28px}.legacyx-staff-section-head h2{font-family:Georgia,serif;font-size:27px;margin:5px 0 20px}.legacyx-staff-modules{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.legacyx-staff-modules article{border:1px solid #e4dfd6;padding:20px}.legacyx-staff-modules article>span{font-size:11px;font-weight:800;letter-spacing:.12em;color:#f05a16}.legacyx-staff-modules h3{font-size:15px;margin:8px 0 18px}.legacyx-staff-modules a,.legacyx-staff-recent a{color:#171512;font-weight:700;text-decoration:none}.legacyx-staff-action{display:block;background:#f7f4ed;color:#171512;text-decoration:none;font-weight:700;padding:14px;margin-bottom:10px;border-left:3px solid #f05a16}.legacyx-staff-recent{margin-top:18px}.legacyx-staff-recent table{width:100%;border-collapse:collapse}.legacyx-staff-recent th,.legacyx-staff-recent td{text-align:left;padding:13px;border-bottom:1px solid #e4dfd6}@media(max-width:1100px){.legacyx-staff-metrics{grid-template-columns:repeat(3,1fr)}.legacyx-staff-grid{grid-template-columns:1fr}}@media(max-width:700px){.legacyx-staff-hero{display:block}.legacyx-staff-hero>a{display:inline-block;margin-top:15px}.legacyx-staff-metrics,.legacyx-staff-modules{grid-template-columns:1fr}.legacyx-staff-metrics>div{border-right:0;border-bottom:1px solid #ded8ce}}';wp_add_inline_style('legacyx-staff-os',$css);}add_action('admin_enqueue_scripts','legacyx_staff_command_styles');
